    visual: { type: 'flow', eyebrow: 'EDIÇÃO SEM PERDA SILENCIOSA', title: 'Salvar sobre a versão conhecida', labels: ['Ler registro e versão', 'Editar o rascunho', 'Verificar a versão', 'Salvar ou comparar', 'Confirmar o resultado'], caption: 'Uma versão desatualizada exige nova decisão. Reenviar automaticamente o mesmo formulário pode sobrescrever uma mudança que a pessoa ainda não viu.' },
