    cta: { title: 'Organize a capacidade das suas integrações', text: 'A Tironi Tech pode desenvolver filas, controle de chamadas e acompanhamento de atraso conforme os limites reais das APIs que sua operação utiliza.', label: 'Avaliar limites da minha integração', href: '/#contato' },
